package com.acme.core.application.warehouselite;

import com.acme.core.application.datascope.DataPermissionContext;
import com.acme.core.application.dictionary.DictionaryPort;
import com.acme.core.common.core.ErrorCode;
import com.acme.core.common.core.PageQuery;
import com.acme.core.common.core.PageResult;
import com.acme.core.common.core.PlatformException;
import com.acme.core.domain.entity.DictionaryItem;
import com.acme.core.domain.entity.WarehouseLite;

import java.time.LocalDateTime;
import java.util.List;

/**
 * WarehouseLite application service (generated by engineering-platform Generic Module Generator).
 * Client never supplies createdBy/departmentId: they come from the authenticated RequestContext.
 */
public class WarehouseLiteService {

    private final WarehouseLitePort warehouseLitePort;
    private final DictionaryPort dictionaryPort;

    public WarehouseLiteService(WarehouseLitePort warehouseLitePort, DictionaryPort dictionaryPort) {
        this.warehouseLitePort = warehouseLitePort;
        this.dictionaryPort = dictionaryPort;
    }

    public WarehouseLiteResponse create(WarehouseLiteCreateRequest request, Long userId, Long departmentId) {
        if (request.code() == null || request.code().isBlank()) {
            throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_CODE_REQUIRED", "code is required"));
        }
        if (warehouseLitePort.existsByUnique(String.valueOf(request.code()), null)) {
            throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_CODE_DUPLICATE", "code already exists"));
        }
        if (request.name() == null || request.name().isBlank()) {
            throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_NAME_REQUIRED", "name is required"));
        }
        validateDictionary("warehouse_status", request.status());
        WarehouseLite warehouseLite = new WarehouseLite();
        warehouseLite.setCode(request.code());
        warehouseLite.setName(request.name());
        warehouseLite.setAddress(request.address());
        warehouseLite.setManager(request.manager());
        warehouseLite.setStatus(request.status());
        warehouseLite.setDepartmentId(departmentId);
        warehouseLite.setCreatedBy(userId);
        LocalDateTime now = LocalDateTime.now();
        warehouseLite.setCreatedAt(now);
        warehouseLite.setUpdatedAt(now);
        warehouseLitePort.insert(warehouseLite);
        return toResponse(warehouseLite);
    }

    public WarehouseLiteResponse get(Long id, DataPermissionContext context) {
        WarehouseLite warehouseLite = warehouseLitePort.findByIdInScope(id, context)
                .orElseThrow(() -> new PlatformException(ErrorCode.of("WAREHOUSE_LITE_NOT_FOUND", "warehouseLite not found: " + id)));
        return toResponse(warehouseLite);
    }

    public List<WarehouseLiteResponse> list(DataPermissionContext context) {
        return warehouseLitePort.findByScope(context).stream().map(this::toResponse).toList();
    }

    public PageResult<WarehouseLiteResponse> page(PageQuery query, DataPermissionContext context) {
        PageResult<WarehouseLite> result = warehouseLitePort.findPageByScope(context, query);
        List<WarehouseLiteResponse> items = result.items().stream().map(this::toResponse).toList();
        return PageResult.of(items, result.total(), result.page(), result.size());
    }

    public PageResult<WarehouseLiteResponse> pageFiltered(PageQuery query, DataPermissionContext context, String keyword, String status) {
        PageResult<WarehouseLite> result = warehouseLitePort.findPageByScopeFiltered(context, query, keyword, status);
        List<WarehouseLiteResponse> items = result.items().stream().map(this::toResponse).toList();
        return PageResult.of(items, result.total(), result.page(), result.size());
    }

    public WarehouseLiteResponse update(Long id, WarehouseLiteUpdateRequest request, DataPermissionContext context) {
        WarehouseLite warehouseLite = warehouseLitePort.findByIdInScope(id, context)
                .orElseThrow(() -> new PlatformException(ErrorCode.of("WAREHOUSE_LITE_NOT_FOUND", "warehouseLite not found: " + id)));
        if (request.code() == null || request.code().isBlank()) {
            throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_CODE_REQUIRED", "code is required"));
        }
        if (warehouseLitePort.existsByUnique(String.valueOf(request.code()), id)) {
            throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_CODE_DUPLICATE", "code already exists"));
        }
        if (request.name() == null || request.name().isBlank()) {
            throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_NAME_REQUIRED", "name is required"));
        }
        validateDictionary("warehouse_status", request.status());
        warehouseLite.setCode(request.code());
        warehouseLite.setName(request.name());
        warehouseLite.setAddress(request.address());
        warehouseLite.setManager(request.manager());
        warehouseLite.setStatus(request.status());
        warehouseLite.setUpdatedAt(LocalDateTime.now());
        warehouseLitePort.update(warehouseLite);
        return toResponse(warehouseLite);
    }

    public WarehouseLiteResponse disable(Long id, DataPermissionContext context) {
        WarehouseLite warehouseLite = warehouseLitePort.findByIdInScope(id, context)
                .orElseThrow(() -> new PlatformException(ErrorCode.of("WAREHOUSE_LITE_NOT_FOUND", "warehouseLite not found: " + id)));
        warehouseLite.setStatus("DISABLED");
        warehouseLite.setUpdatedAt(LocalDateTime.now());
        warehouseLitePort.update(warehouseLite);
        return toResponse(warehouseLite);
    }

    private void validateDictionary(String code, String value) {
        if (value == null || value.isBlank()) return;
        dictionaryPort.findTypeByCode(code).ifPresent(type -> {
            java.util.Set<String> values = dictionaryPort.findItemsByTypeId(type.getId()).stream()
                    .map(DictionaryItem::getValue).collect(java.util.stream.Collectors.toSet());
            if (!values.isEmpty() && !values.contains(value)) {
                throw new PlatformException(ErrorCode.of("WAREHOUSE_LITE_DICTIONARY_INVALID", "value not in dictionary " + code + ": " + value));
            }
        });
    }

    private WarehouseLiteResponse toResponse(WarehouseLite e) {
        return WarehouseLiteResponse.of(e.getId(), e.getCode(), e.getName(), e.getAddress(), e.getManager(), e.getStatus(), e.getDepartmentId(), e.getCreatedBy(), e.getCreatedAt(), e.getUpdatedAt());
    }
}
